{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "@cheesecodestudio/opencode-tokenscope-v2",
  "version": "2.0.0",
  "description": "OpenCode plugin for detailed token usage analysis with breakdowns by category, visual charts, and subagent cost tracking",
  "type": "module",
  "main": "./dist/tokenscope.js",
  "types": "./dist/tokenscope.d.ts",
  "exports": {
    ".": {
      "types": "./dist/tokenscope.d.ts",
      "import": "./dist/tokenscope.js"
    }
  },
  "scripts": {
    "clean": "node -e \"import('node:fs').then(fs => fs.rmSync('dist', { recursive: true, force: true }))\"",
    "build": "node -e \"import('node:fs').then(fs => fs.rmSync('dist', { recursive: true, force: true }))\" && tsc",
    "test": "bun test",
    "test:dist": "node -e \"await import('./dist/tokenscope.js')\"",
    "prepublishOnly": "npm run build",
    "typecheck": "tsc --noEmit"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "plugin",
    "tokens",
    "token-usage",
    "analysis",
    "cost-tracking"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/cheesecodestudio/opencode-tokenscope-v2.git"
  },
  "bugs": {
    "url": "https://github.com/cheesecodestudio/opencode-tokenscope-v2/issues"
  },
  "homepage": "https://github.com/cheesecodestudio/opencode-tokenscope-v2#readme",
  "author": "ramtinj95",
  "license": "MIT",
  "dependencies": {
    "@opencode/plugin": "2.0.18",
    "@huggingface/tokenizers": "^0.1.3",
    "js-tiktoken": "^1.0.15"
  },
  "devDependencies": {
    "@types/bun": "^1.2.0",
    "@types/node": "^22.0.0",
    "typescript": "^5.7.0"
  },
  "files": [
    "index.js",
    "dist/",
    "models.json",
    "tokenscope-config.json",
    "README.md",
    "LICENSE"
  ]
}
